          const nx = -(po[1] - eo[1]), ny = po[0] - eo[0], nl = Math.hypot(nx, ny) || 1;
          lab("R", (eo[0] + pe[0]) / 2 + nx / nl * 11, (eo[1] + pe[1]) / 2 + ny / nl * 11, C.meas, { align: "center", weight: 700, size: FS });
          lab("H", (pe[0] + po[0]) / 2 + nx / nl * 11, (pe[1] + po[1]) / 2 + ny / nl * 11, C.new, { align: "center", weight: 700, size: FS });
