          { k: "СОИ 1 ทำงานที่", v: m.soi1.map(tsub).join(" · "), note: m.soi1.filter(t => t < m.j0 + m.NN).length + " ครั้งต่อรอบใหญ่ = n<sub>2</sub>" },
          { k: "รอบที่ " + (m.NN + 1), v: m.pairs[m.NN] + " = รอบที่ 1 " + m.pairs[0], big: true, note: "ตรวจเครื่องแต่ละชิ้นใช้เต็ม: " + m.n1 + " · (" + TP[0] + " + " + TRr + ") = " + m.chk1 + " และ " + m.n2 + " · (" + TP[1] + " + " + TRr + ") = " + m.chk2 + " จังหวะ " + ED("ผู้เรียบเรียงตรวจ") }
