        const SUB = ["потребитель СИ", "КПИ для СБО", narrow ? "КПИ ОБО ⊕ СБО" : "ГУ · КПИ для ОБО ⊕ СБО", narrow ? "СС и ПД" : "СС и ПД ЦУП → КС", narrow ? "АКПП · ПП СЕВ" : "АКПП КПИ · ПП СЕВ (МВ)", "БКУ · СБО"];

