          if (i === 2 && k === 2) {   // этап 3 — «пульс» объединения массивов внутри ПУ ЦУП
            ctx.save(); ctx.globalAlpha = 0.35 + 0.35 * Math.sin(ph * Math.PI * 2);
            rrect(ctx, b.x - 3, b.y - 3, b.w + 6, b.h + 6, 6, null, ac2, 2); ctx.restore();
          }
          const two = bh >= 34;
          TX(ctx, NAME[i], b.cx, two ? b.cy - (fsS + 3) / 2 : b.cy, on ? ink : ink2, "center", "middle", fs, "700");
          if (two) TX(ctx, SUB[i], b.cx, b.cy + (fs + 3) / 2, on ? ink2 : ink3, "center", "middle", fsS);
