        const ml = narrow ? 22 : 30, mr = 8, W = w - ml - mr;
        /* вертикальные полосы: заголовок (12) · дорожка · подписи оси (14) · зазор … */
        const TH = fsS + 5, free = h - (TH + 14 + 6 + TH + 13 + 8 + TH + 14 + 2);
        const H1 = Math.round(free * (narrow ? 0.40 : 0.44)), H2 = Math.round(free * (narrow ? 0.30 : 0.28)), H3 = free - H1 - H2;
        const y1 = TH, y2 = y1 + H1 + 14 + 6 + TH + 13, y3 = y2 + H2 + 8 + TH;
        const Tw = FRAMES * Tlk;                       // окно верхней дорожки, с
        const X1 = t => ml + W * t / Tw;               // время → x (верх)
        const X2 = t => ml + W * t / Tlk;              // время → x (кадр 1)

