        TX(ctx, narrow ? "1 · U(t) เซนเซอร์ และจุดอ่าน" : "1 · อินพุต: U(t) ของเซนเซอร์ 1–3 และจุดอ่าน (หนึ่งครั้งต่อเฟรม T лк)", ml, y1 - 4, ink3, "left", "bottom", fsS);
        ctx.save(); ctx.fillStyle = wash; ctx.fillRect(X1(0), y1, X1(Tlk) - X1(0), H1); ctx.restore();   // кадр 1 — увеличен ниже
        ctx.save(); ctx.strokeStyle = grid; ctx.lineWidth = 1;
        for (let m = 0; m <= FRAMES; m++) { const x = Math.round(X1(m * Tlk)) + .5; ctx.beginPath(); ctx.moveTo(x, y1); ctx.lineTo(x, y1 + H1); ctx.stroke(); }
        ctx.restore();
        hline(ctx, ml, ml + W, y1 + H1, line2, 1);
        vline(ctx, ml, y1, y1 + H1, line2, 1);
        TX(ctx, "U", ml - 4, y1 + 2, ink3, "right", "top", fsS);
        TX(ctx, "0", ml - 4, y1 + H1, ink3, "right", "middle", fsS);
        const tickEvery = narrow ? 5 : 2;
        for (let m = 0; m <= FRAMES; m += tickEvery) TX(ctx, n2(m * Tlk * 1000, 0), X1(m * Tlk), y1 + H1 + 3, ink3, m === FRAMES ? "right" : (m === 0 ? "left" : "center"), "top", fsS);
        TX(ctx, "t, мс", ml + W, y1 - 4, ink3, "right", "bottom", fsS);
        /* линии сигналов */
        for (let c = 2; c >= 0; c--) {
          ctx.save(); ctx.strokeStyle = COL[c]; ctx.lineWidth = c === 0 ? 1.8 : 1.2; ctx.globalAlpha = c === 0 ? 1 : 0.8; ctx.beginPath();
          const n = 400;
          for (let i = 0; i <= n; i++) { const t = Tw * i / n, y = y1 + H1 - U[c](t) * H1; i ? ctx.lineTo(X1(t), y) : ctx.moveTo(X1(t), y); }
          ctx.stroke(); ctx.restore();
        }
