            ctx.save(); ctx.fillStyle = COL[c]; ctx.strokeStyle = CV("--panel"); ctx.lineWidth = 1;
            ctx.beginPath(); ctx.arc(x, y, c === 0 ? 3.2 : 2.4, 0, 7); ctx.fill(); if (c === 0) ctx.stroke(); ctx.restore();
