        { id: "emax", label: "ε max — มุมเงยสูงสุดของการผ่าน, °", min: 10, max: 90, step: 1, value: 60, fmt: v => n2(v, 0) + "°" },
        { id: "f0", label: "f₀ — ความถี่พาหะ, МГц", min: 100, max: 8000, step: 50, value: 2000, fmt: v => nInt(v) + " МГц" },
        { id: "tt", label: "t — ตำแหน่งบนช่วงสัญญาณ (−1 … +1 ของครึ่งช่วง)", min: -1, max: 1, step: 0.01, value: -0.5, fmt: v => n2(v, 2) }
