  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  /* чч.мм из минут суток (формат плана сл. 8: «10.51») */
  function hm(m) { m = Math.round(m); const hh = Math.floor(m / 60) % 24, mm = m % 60; return (hh < 10 ? "0" : "") + hh + "." + (mm < 10 ? "0" : "") + mm; }
  /* детерминированный генератор (mulberry32) — «вариант» = seed */
