        ctx.save(); ctx.strokeStyle = grid; ctx.setLineDash([3, 3]); ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(F[0], F[1], r20 * sc, 0, 7); ctx.stroke(); ctx.restore();
        // Земля
        ctx.save(); ctx.fillStyle = wash; ctx.strokeStyle = ac; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(F[0], F[1], RE * sc, 0, 7); ctx.fill(); ctx.stroke(); ctx.restore();
        if (RE * sc > 9) TX(ctx, "โลก", F[0], F[1], ac, "center", "middle", Math.min(fs, RE * sc * 0.55), "600");
        // радиус-вектор
        const Q = S(P.x, P.y);
        ctx.save(); ctx.strokeStyle = line2; ctx.setLineDash([4, 3]); ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(F[0], F[1]); ctx.lineTo(Q[0], Q[1]); ctx.stroke(); ctx.restore();
        // вектор скорости: касательная, длина ∝ v
