      const cg = clamp(Math.cos(phi) * Math.cos(dl), -1, 1), g = Math.acos(cg), sg = Math.sin(g);
      const eps = g < 1e-9 ? 90 : Math.atan((cg - RE / R_GSO) / sg) / D2R;
