  function n2(v, d) { d = (d === undefined) ? 2 : d; if (!isFinite(v)) return "—"; return (Math.abs(v) < Math.pow(10, -d - 1) ? 0 : v).toFixed(d).replace(".", ","); }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function dot(ctx, x, y, r, fill, stroke) { ctx.save(); ctx.fillStyle = fill; ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill(); if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke(); } ctx.restore(); }

  const RE = 6371, MU = 398600.44, TSID = 86164;

