                    // L = 1 м — допущение составителя (assumed), на графике подписано и показано полым маркером
      { name: "Ресурс-П", h: 475, L: 0.7 }, { name: "Канопус-В", h: 675, L: 2.5 }, { name: "Кондор", h: 520, L: 1.0, assumed: true }
